sys_security_acl.script:
answer = false;

var userId = gs.getUserID();
var appId = current.getValue('application');
var driveId = current.getValue('drive');

var appGr = new GlideRecord('x_snc_college_pl_0_application');

if (appId) {

    appGr.addQuery('sys_id', appId);
    appGr.addQuery('student.user', userId);
    appGr.setLimit(1);
    appGr.query();

    if (appGr.next()) {
        answer = true;
    }

} else if (driveId) {

    appGr.addQuery('drive', driveId);
    appGr.addQuery('student.user', userId);
    appGr.setLimit(1);
    appGr.query();

    if (appGr.next()) {
        answer = true;
    }
}
